const PREFIX = 'rawdha-parent-access-v1';
const TOKEN = /^[a-f0-9]{64}$/;

// This is a temporary bearer secret: never put it in a URL, log, or analytics.
export function encodeParentAccessTransfer(token: string, origin: string): string {
  if (!TOKEN.test(token)) throw new Error('invalid_transfer');
  return `${PREFIX}\n${origin}\n${token}`;
}

export function decodeParentAccessTransfer(value: string, origin: string): string | null {
  const text = value.trim();
  // Support codes generated by the previous version for manual recovery.
  if (TOKEN.test(text)) return text;
  const parts = text.split('\n');
  if (parts.length !== 3 || parts[0] !== PREFIX || parts[1] !== origin || !TOKEN.test(parts[2])) return null;
  return parts[2];
}
